      "answer": "Kortaste lämpliga väg till besiktningsorgan för besiktning. Vid inträtt körförbud får fordonet också köras kortaste lämpliga väg till reparationsverkstad för reparation. FoF 6 kap. 21 §. Andra hinder, till exempel avställning eller trafikfarligt skick, måste prövas separat.",
