      "prompt": "Vilka är de tillåtna färderna på en personbil som: (3p)\n\nHar användningsförbud p.g.a. obetald vägtrafikskatt?",
      "answer": "Det finns inget vanligt undantag som tillåter exempelvis färd till besiktning när användningsförbud på grund av obetald skatt gäller. VTSL 6 kap. 1 § reglerar förbudet och dess särskilda undantag. Lärarsvarets ”inga färder alls” är ett kort svar under den givna förutsättningen att förbudet faktiskt gäller; kontrollera bland annat om undantag eller befrielse enligt lag har beslutats.",
