      "title": "Bilförarens skyldighet",
      "prompt": "Du färdas som privatperson i personbil på Sallerupsvägen i Malmö och kommer fram till platsen enligt bild.\n\nc) Vad har du som bilförare för skyldighet om det finns en cyklist som är på väg ut på \"cykelmiljön\" när du närmar dig platsen (du befinner dig då ca 20 meter från \"miljön\") och i vilket lagrum regleras detta? (1p)",
      "answer": "Väjningsplikt mot cyklande och moped klass II som är ute på eller just ska färdas ut på cykelöverfarten, TrF 3 kap. 61 a §. Anpassa hastigheten i tid. Bedöm den beskrivna situationen, inte en generell regel att cyklisten alltid har rätt att köra ut utan hänsyn.",
