      "year": 2022,
      "original": "12c",
      "category": "Ingripande & körförbud",
      "title": "Färder efter missad besiktning",
      "prompt": "Du äger en \"äldre\" personbil, Volvo V70, som togs i bruk första gången 2003 och pb:n har sedan varit i trafik sedan dess och besiktigats flera gånger.\n\nc) Tiden har nu löpt ut och dagens kontrollbesiktning är inte längre giltig. Du har inte inställt pb:n till ny periodisk kontrollbesiktning - Vilken/Vilka färder får du nu göra?  Ange lagrum för var detta regleras.",
      "answer": "Kortaste lämpliga väg till besiktningsorgan för besiktning och, vid denna typ av körförbud, till reparationsverkstad för reparation. FoF 6 kap. 21 § andra stycket. Det är inget generellt tillstånd för privata ärenden eller för färd hem från verkstad.",
