      "title": "När är drograttfylleri grovt?",
      "prompt": "d) När blir det grovt rattfylleri under påverkan av droger? (2p)",
      "answer": "Bedöm särskilt avsevärd påverkan eller påtaglig fara för trafiksäkerheten enligt TBL 4 a §. Det finns inget generellt numeriskt narkotikagränsvärde för grovt brott. Helhetsbedömningen är avgörande. NJA 2025 s. 211 klargör att narkotikapåverkan inte måste ha orsakat den trafikfarliga körningen.",
      "sources": [
        "tbl",
        "hd2025"
      ],
      "choices": [],
      "teacher": "För poäng krävs hänvisning till både punkten 2 och 3 i TBL4a§. Då de inte har böcker så är det tillräckligt med en förklaring om att föraren varit avsevärt påverkad (1p) och att framförandet av fordonet inneburit en påtaglig fara för trafiksäkerheten (1p). Här kan förekomma olika sätt att beskriva detta. De delar vi kan tolka in i svaren ger ett halvt poäng vardera. (1p)",
