      "exam": "dk1",
      "year": 2022,
      "original": "5c",
      "category": "Trafikbrott",
      "title": "Målsägande vid skadorna",
      "prompt": "Ni blir beordrade till en trafikolycka på E65 i höjd med Rydsgård i östlig färdriktning. När ni kommer fram så ser ni att PB MLB 365 har kört in i mittvajerräcket och kört ner sju stolpar. Olyckan har inträffat 2022-02-01 kl. 18.40. Omfattande skador på fordonet i fronten och längs vänster sidan. Vänster framdäck har slitits av från fälgen. Vajerräcket har gjort att fordonet inte kom över i mötande körfält. Brandkåren är på plats och har spärrat av trafiken i östlig riktning vilket skapat långa köer i trafiken. Föraren Ewa Svensson var ensam i bilen och är oskadad. Ewa berättar i förhör på platsen att hon var på väg hem från sitt arbete i Arlöv. Ewa hade börjat tidigt idag kl. 06.00, som hon brukar göra. Arbetsdagen blev lite längre än vanligt och hon började sin hemfärd först kl. 18.00. Det var gråmulet väder och småregnade hela vägen och trafiken gick långsamt, runt 70 km/tim. Ewa kände sig lite småtrött, men drack kaffe och lyssnade på musik och var nästan hemma. Hon skulle svänga av vid nästa avfart. Hon kan inte säga vad som hände. Hon vaknade av att hon kört in i mitträcket. Bilen var utan anmärkning i VTR och stod registrerad på Ewas pappa Erik Svensson.\n\nc) Vilka parter för ni in som målsägande i denna händelse? (2p)",
      "answer": "Utred ägaren till den skadade bilen (pappan enligt uppgiften) och väghållaren/ägaren till det skadade vajerräcket. Kontrollera vem som faktiskt äger egendomen och vem ett anspråk tillkommer. Skadad egendom eller en trafikstörning gör inte automatiskt varje berörd person till målsägande; tillämpa RB 20 kap. 8 § och dokumentera skadan och anspråket.",
