      "title": "Afghanskt körkort i Sverige",
      "prompt": "Mohammed, 45 år, visar ett giltigt B-körkort från Afghanistan. Du förstår inte texten. Han har precis fått uppehållstillstånd och kontaktat Skatteverket för folkbokföring. Vad krävs för giltighet i Sverige och hur länge gäller det? (2p)",
      "answer": "Körkortet ska vara giltigt i utfärdandelandet och ge rätt behörighet. Om det inte följer konventionsmodellen och inte är utfärdat på engelska, tyska eller franska krävs bestyrkt översättning till ett tillåtet språk. Saknas foto behövs legitimation med foto. Huvudregeln för Afghanistan är att körkortet inte gäller efter mer än ett års folkbokföring i Sverige. Tiden räknas från folkbokföringen, inte uppehållstillståndet. KKL 6 kap. 1–2 §§; kontrollera övriga hinder.",
