      "answer": "Lärarsvarsmallen anger A, vilket ger motorcykelbehörighet. Bilden saknar dock de tekniska uppgifter som behövs för att utesluta A1 eller A2 som lägsta behörighet. För A2 behövs bland annat högst 35 kW, högst 0,2 kW/kg och rätt ursprungseffekt. För A1 gäller bland annat 125 cm³, 11 kW och 0,1 kW/kg. Kontrollera registreringsuppgifterna, KKL 2 kap. 5 §.",
