      "prompt": "Vilka färder är tillåtna med ett fordon som har ett inträtt (automatiskt) körförbud? (2p)",
      "answer": "Kortaste lämpliga väg till besiktningsorgan för besiktning. Vid inträtt körförbud även kortaste lämpliga väg till reparationsverkstad för reparation. FoF 6 kap. 21 §. Pröva avställning, försäkring, skatt och trafikfarligt skick separat.",
