      "id": "dk1-14b",
      "exam": "dk1",
      "year": 2022,
      "original": "14b",
      "category": "Strategi & trafikregler",
      "title": "Barnet skjutsas utan hjälm",
      "prompt": "En förälder cyklar med ett cirka treårigt barn i cykelsadel på sin tvåhjuliga cykel. Barnet saknar hjälm. Kan föräldern bötfällas? Motivera. (del av 2p)",
      "answer": "Ja, den som för cykeln ska se till att passagerare under 15 år använder hjälm eller annat lämpligt huvudskydd. Uppsåt eller oaktsamhet krävs för ansvar. TrF 6 kap. 4 a § och 14 kap. 6 a §; normal ordningsbot 500 kr enligt bilaga 1A nr 5.3.",
