      "title": "Tyskt körkort och bosättning",
      "prompt": "En tysk medborgare, boende i Sverige, har ett tyskt körkort. Hur länge är det giltigt i Sverige? (1p)",
      "answer": "Ett giltigt tyskt EES-körkort gäller i Sverige även efter mer än ett års folkbokföring, under förutsättning att det inte finns ett annat giltighetshinder. Kontrollera kortets giltighet i utfärdandelandet och KKL 6 kap. 1–2 §§. Det betyder inte att körkortet gäller för alltid oavsett kortets slutdatum eller återkallelse.",
