      "answer": "Uppgiften pekar på moped klass II om den konstruktiva hastigheten är högst 25 km/h och övriga mopedvillkor uppfylls, LDEF 2 §. En vanlig elcykel kräver trampassistans och högst 250 W kontinuerlig märkeffekt. Kontrollera konstruktiv hastighet; att motorn slutar ge tillskott är inte alltid en fullständig teknisk klassificering.",
