      "title": "Fordon B – 20 km/h och 250 W",
      "prompt": "Vad är fordonsslaget? Eldrivet fordon utan tramp- eller vevanordning, konstruerat för högst 20 km/h och elmotor max 250 W. I PDF:n står även: ”Får framföras på gångbana i gångfart enligt TraF.” (1 av 3p)",
      "answer": "En elsparkcykel av detta slag kan vara cykel enligt LDEF 2 §. Påståendet om gångbana är föråldrat för vanlig elsparkcykelkörning: sedan 1 september 2022 omfattas den inte längre av gåendereglerna vid gångfart. Se TrF 1 kap. 4 § och 3 kap. 6 §. Särregler finns bland annat för rullstol, vissa hjälpmedel och självbalanserande cyklar i gångfart. Även barns cykling regleras särskilt i 3 kap. 12 a §. Att leda fordonet är en annan situation.",
