      "prompt": "Polisens strategi för trafik som metod beskriver fyra fokusområden. Vilka? (4p)",
      "answer": "Trafiksäkerhetsarbete, trygghetsskapande arbete, yrkestrafik och brott på väg. Detta är fokusområdena i kursens strategisammanhang. Skilj dem från de fyra målen som efterfrågas i Wordövningen.",
