      "answer": "Rätt är vid backning, vid färd inom de uppräknade begränsade områdena och när fordonet inte är i rörelse, TrF 4 kap. 10 d §. Att vara taxi-, lastbils- eller bussförare är inte i sig något generellt undantag. Andra särskilda undantag måste prövas för sig.",
