      "prompt": "Personbil: totalvikt 2 500 kg, uppmätt vikt 2 470 kg, maximal släpvagnsvikt 1 300 kg. Släp: totalvikt 1 000 kg, uppmätt vikt 1 160 kg. Föraren äger ekipaget och har A, B och C. Vad rapporterar du och hur?",
      "answer": "Behörighet: 2 500 + 1 000 = 3 500 kg, alltså räcker B. Bilens vikt och draggräns är inte överskridna. Släpet har 160 kg överlast, 16 % av totalvikten. Utred förarens kännedom eller vad föraren borde ha känt till. TrF 4 kap. 4 § och 14 kap. 4 §; ordningsbot i normalfallet 2 000 kr enligt bilaga 1A nr 11.6 (15–19 %). Vid mer än 10 % ska avlastning/omlastning säkerställas enligt 14 kap. 16 §. Erkännande, fullständiga omständigheter och förutsättningarna i RB 48 kap. måste finnas för ordningsbot.",
