      "title": "Tre viktbegrepp",
      "prompt": "Förklara tjänstevikt, bruttovikt och totalvikt för en bil.",
      "answer": "Tjänstevikt: bilen i normalt, fullt driftfärdigt skick med bland annat förare, bränsle, olja, vatten, verktyg och reservhjul som hör till fordonet. Bruttovikt: den vikt som fordonets hjul, band eller medar vid ett visst tillfälle för över till vägbanan. Totalvikt: tjänstevikt plus beräknad vikt av största tillåtna antal passagerare utom föraren och största mängd gods. LDEF 2 §. Behörighet prövas normalt med totalvikterna; faktisk belastning med de aktuella vikterna.",
