      "prompt": "Personbil med släp kör 99 km/h på 90-väg. Släpets däck saknar synligt mönsterdjup. En bokhylla är helt osäkrad. Föraren är ägare, har BE och erkänner. Utred överträdelser och gemensam bot.",
      "answer": "Om ekipaget omfattas av den vanliga 80-gränsen för bil med släp är överträdelsen 19 km/h: 2 400 kr, bilaga 1A hastighetstabell. Kontrollera släpets broms-/viktförutsättningar enligt TrF 4 kap. 20 §; originalet anger inte dessa och 80 km/h är ett redovisat antagande. Otillräckligt profildjup: 1 200 kr, bilaga 1B nr 3.1. Lastsäkringsbrist: utred risk enligt TrF 3 kap. 80 §, bilaga 1A nr 2.74. Enbart föreskriftsbrist 1 500 kr ger 3 750 kr tillsammans med 2 400 och 1 200. Om lasten kan falla av: 2 000 kr och total 4 000 kr. Fara för person: 3 000 kr och total 4 800 kr. Välj utifrån dokumenterade fakta, inte det lägsta alternativet på rutin. Säkerställ säker last och hantera farliga däck före fortsatt färd.",
