      "prompt": "Vilken vanlig undantagsfärd tillåts och vad måste kontrolleras?",
      "answer": "LFRA 10 § 4 tillåter kortaste lämpliga väg till eller från närmaste besiktningsorgan för besiktning, om fordonet ställts av på ägarens begäran och inte omfattas av angivna användningsförbud. Trafikförsäkring måste finnas när ett försäkringspliktigt fordon brukas. Kontrollera skatt/användningsförbud, besiktningssyfte och trafiksäkert skick. Undantaget innebär inte allmän rätt att köra till verkstad med en avställd bil. Andra särskilda undantag finns i 10 § men är inte den vanliga privata besiktningsfärden.",
