      "prompt": "Förklara begreppet och ge ett exempel från polisarbete.",
      "answer": "Traumarelaterade stressreaktioner kan uppstå genom nära kontakt med andras traumatiska upplevelser, även utan att man själv utsatts för samma händelse. Exempel: en utredare som upprepade gånger tar del av svåra berättelser får påträngande minnesbilder, sömnsvårigheter eller undvikande. Skilj detta från vanlig tillfällig stress och från att själv direkt uppleva en traumatisk händelse. Begreppet är inte i sig en individuell PTSD-diagnos.",
